// Actividades de opción única. El código se muestra como texto: no se ejecuta.
// Cada actividad enseña el concepto antes de preguntar.
const activity = (id, courseId, title, concept, code, question, options, answer, explanation) => ({
  id, courseId, type: 'single-choice', title, concept, code, question,
  options: options.map((label, index) => ({ id: String.fromCharCode(97 + index), label })),
  answerId: String.fromCharCode(97 + answer), explanation
})

